mapper.select:
SELECT game_id, rune_key, name, description, category, created_at, updated_at FROM public.runes
WHERE game_id = #{gameId}

    AND (strpos(lower(rune_key), lower(#{keyword})) > 0 OR strpos(lower(name), lower(#{keyword})) > 0)

AND category = #{category}
ORDER BY name ASC, rune_key ASC

SELECT COUNT(*) FROM public.runes
WHERE game_id = #{gameId} AND lower(btrim(name)) = lower(btrim(#{name}))
AND rune_key <> #{excludeKey}

mapper.update:
UPDATE public.runes SET name = #{name}, description = #{description},
    category = #{category}, updated_at = now()
WHERE game_id = #{gameId} AND rune_key = #{runeKey}

mapper.select:
SELECT game_id, path_key, name, description, kind, sort_order, slots::text AS slots_json, created_at, updated_at FROM public.rune_paths WHERE game_id = #{gameId}
AND (strpos(lower(path_key), lower(#{keyword})) > 0 OR strpos(lower(name), lower(#{keyword})) > 0)
ORDER BY sort_order ASC, path_key ASC

SELECT COUNT(*) FROM public.rune_paths
WHERE game_id = #{gameId} AND lower(btrim(name)) = lower(btrim(#{name}))
AND path_key <> #{excludeKey}

mapper.update:
UPDATE public.rune_paths SET name = #{name}, description = #{description},
    kind = #{kind}, sort_order = #{sortOrder}, slots = CAST(#{slotsJson} AS jsonb), updated_at = now()
WHERE game_id = #{gameId} AND path_key = #{pathKey}
